from text import truncate


def test_word_boundary():
    assert truncate('hello world foo', 12) == 'hello world'


def test_no_truncation_needed():
    assert truncate('short', 12) == 'short'


def test_single_long_word_is_hard_cut():
    assert truncate('abcdefghijklmno', 5) == 'abcde'
